/**
 * TASK: Complete RegularPolygonShape, which implements the provided Scalable
 * interface. Measurable2D and Scalable are provided -- do not edit them.
 *
 * Note that Scalable EXTENDS Measurable2D: implementing Scalable therefore
 * obliges you to supply area() and perimeter() as well as scaled(), and hands
 * you two default methods written in terms of them.
 *
 * A regular polygon has "sides" equal edges of length "sideLength":
 *
 *   perimeter = sides * sideLength
 *   area      = sides * sideLength^2 / (4 * tan(PI / sides))
 *
 * A square (4 sides of length 2) therefore has perimeter 8 and area 4.0, and a
 * hexagon of side 1 has area 2.6 when rounded to two decimals.
 *
 * scaled(factor) must return a NEW RegularPolygonShape with the same number of
 * sides and every edge multiplied by factor -- and note the declared return
 * type: it is narrower than the Scalable the interface promises, which Java
 * allows and which lets callers keep the concrete type.
 */
interface Measurable2D {

    double area();

    double perimeter();
}

interface Scalable extends Measurable2D {

    Scalable scaled(double factor);

    default double areaRatioTo(Measurable2D other) {
        return Math.round(area() / other.area() * 100.0) / 100.0;
    }

    default boolean largerThan(Measurable2D other) {
        return area() > other.area();
    }
}

public class RegularPolygonShape implements Scalable {

    private final int sides;
    private final double sideLength;

    public RegularPolygonShape(int sides, double sideLength) {
        this.sides = sides;
        this.sideLength = sideLength;
    }

    public int getSides() {
        return sides;
    }

    public double getSideLength() {
        return sideLength;
    }

    @Override
    public double perimeter() {
        // TODO: every edge is the same length
        return 0.0;
    }

    @Override
    public double area() {
        // TODO: sides * sideLength^2 / (4 * Math.tan(Math.PI / sides))
        return 0.0;
    }

    @Override
    public RegularPolygonShape scaled(double factor) {
        // TODO: a new polygon with the same number of sides
        return null;
    }
}

