public class RegularPolygonShapeTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static Object round2(java.util.function.Supplier<Double> body) {
        try {
            return Math.round(body.get() * 100.0) / 100.0;
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        RegularPolygonShape square = new RegularPolygonShape(4, 2);
        RegularPolygonShape hexagon = new RegularPolygonShape(6, 1);
        RegularPolygonShape triangle = new RegularPolygonShape(3, 2);

        check("square perimeter", 8.0, round2(square::perimeter));
        check("square area", 4.0, round2(square::area));
        check("hexagon area", 2.6, round2(hexagon::area));
        check("triangle area", 1.73, round2(triangle::area));

        RegularPolygonShape bigger = square.scaled(2);
        check("scaled keeps the side count", 4, safe(() -> bigger.getSides()));
        check("scaled doubles the perimeter", 16.0, round2(() -> bigger.perimeter()));
        check("scaled quadruples the area", 16.0, round2(() -> bigger.area()));
        check("scaled leaves the original alone", 4.0, round2(square::area));

        check("inherited areaRatioTo", 4.0, round2(() -> bigger.areaRatioTo(square)));
        check("inherited largerThan", Boolean.TRUE, safe(() -> bigger.largerThan(square)));
        check("largerThan the other way round", Boolean.FALSE,
                safe(() -> square.largerThan(bigger)));

        Measurable2D asMeasurable = hexagon;
        check("through the parent interface", 6.0, round2(asMeasurable::perimeter));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
