interface Measurable2D {

    double area();

    double perimeter();
}

interface Scalable extends Measurable2D {

    Scalable scaled(double factor);

    default double areaRatioTo(Measurable2D other) {
        return Math.round(area() / other.area() * 100.0) / 100.0;
    }

    default boolean largerThan(Measurable2D other) {
        return area() > other.area();
    }
}

public class RegularPolygonShape implements Scalable {

    private final int sides;
    private final double sideLength;

    public RegularPolygonShape(int sides, double sideLength) {
        this.sides = sides;
        this.sideLength = sideLength;
    }

    public int getSides() {
        return sides;
    }

    public double getSideLength() {
        return sideLength;
    }

    @Override
    public double perimeter() {
        return sides * sideLength;
    }

    @Override
    public double area() {
        return sides * sideLength * sideLength / (4 * Math.tan(Math.PI / sides));
    }

    @Override
    public RegularPolygonShape scaled(double factor) {
        return new RegularPolygonShape(sides, sideLength * factor);
    }
}
